COPY public.document (documentid, title, category, description, content, ownerid, uploadedby, updatedat) FROM stdin;
1	Leave policy 2026	Policies	Leave types, yearly entitlement and how to apply.	LEAVE POLICY 2026\n\n1. Entitlement\n- Earned leave: 18 days a year, credited monthly (1.5 days).\n- Casual leave: 8 days a year.\n- Sick leave: 10 days a year. A medical certificate is needed for more than 2 consecutive days.\n- Maternity leave: 26 weeks. Paternity leave: 2 weeks.\n- Compensatory off: 1 day for each weekend or holiday worked, used within 60 days.\n\n2. Applying\nApply through My services > Time off at least 3 working days before planned leave. Emergency and sick leave can be applied on the day.\n\n3. Carry forward\nUp to 30 days of earned leave carry forward to the next year. Casual and sick leave lapse on 31 December.\n\n4. Approval\nYour reporting manager approves or rejects requests within 2 working days.	\N	HR Team	2026-10-17 03:29:56.465208
2	Code of conduct	Policies	How we work with each other, customers and partners.	CODE OF CONDUCT\n\nRespect: treat every colleague, customer and partner with dignity. Harassment and discrimination of any kind are not tolerated.\n\nIntegrity: be honest in your work, records and expense claims. Declare any conflict of interest to HR.\n\nConfidentiality: protect company, customer and employee information. Share it only with people who need it for their work.\n\nSpeaking up: report concerns to your manager, HR or the confidential ethics line. Nobody will face retaliation for raising a concern in good faith.	\N	HR Team	2026-07-29 03:29:56.465208
3	Information security policy	IT	Passwords, devices, email and data handling rules.	INFORMATION SECURITY POLICY\n\n- Use a unique password of at least 12 characters. Never share it; IT will never ask for it.\n- Lock your screen whenever you leave your desk (Windows + L).\n- Report lost or stolen laptops and phones to IT within 1 hour.\n- Do not install unapproved software or connect personal USB drives to company laptops.\n- Treat unexpected attachments and links as suspicious. Forward phishing emails to security@company.com.\n- Customer data must stay in approved systems and must never be copied to personal accounts.	\N	HR Team	2026-11-01 03:29:56.465208
4	Travel and expense policy	Finance	Booking travel and claiming expenses.	TRAVEL AND EXPENSE POLICY\n\nBooking: book flights and hotels through the travel desk at least 7 days ahead.\n\nDaily allowance: Rs 1,500 within India for meals and local travel.\n\nClaims: submit expenses with receipts within 30 days of returning. Claims are paid with the next salary.\n\nNot covered: alcohol, personal entertainment, fines and upgrades you chose yourself.	\N	HR Team	2026-09-12 03:29:56.465208
5	Work from home guidelines	Policies	Eligibility and expectations for remote days.	WORK FROM HOME GUIDELINES\n\n- Up to 2 work-from-home days a week, agreed with your manager.\n- Apply in My services > Time off with the type "Work From Home".\n- Be reachable on chat and phone between 10:00 and 17:00.\n- Use the company VPN for all work systems.\n- Internet reimbursement: up to Rs 1,000 a month.	\N	HR Team	2026-11-11 03:29:56.465208
6	Holiday calendar 2027	General	Company holidays for next year.	HOLIDAY CALENDAR 2027\n\n26 Jan - Republic Day\n14 Apr - Tamil New Year / Ambedkar Jayanti\n1 May - May Day\n15 Aug - Independence Day\n2 Oct - Gandhi Jayanti\n29 Oct - Diwali\n25 Dec - Christmas\n\nPlus 2 floating holidays of your choice, applied as casual leave.	\N	HR Team	2026-11-23 03:29:56.465208
7	Employee handbook	General	Everything a new joiner needs in the first month.	EMPLOYEE HANDBOOK\n\nWelcome to the company!\n\nWorking hours: 9:30 to 18:30, Monday to Friday, with a one-hour lunch break.\nPayday: the last working day of each month. Payslips appear in My services > Payslips.\nProbation: 6 months, followed by a confirmation review with your manager.\nLearning: borrow books and courses from the Library page.\nHelp: raise a ticket on the Help & support page for IT, HR, payroll or facilities questions.	\N	HR Team	2026-05-10 03:29:56.465208
8	Offer letter	Personal	Your offer of employment.	OFFER OF EMPLOYMENT\n\nDear Hari Adams,\n\nWe are pleased to offer you the position of Associate Software Engineer in Department 5 (Mumbai), starting on 2 April 2023.\n\nYour monthly gross salary will be Rs 31,472.18.\n\nWelcome aboard!\nHR Team	1	HR Team	2023-04-02 00:00:00
