-- Data for Name: faq; Type: TABLE DATA; Schema: public; Owner: -
--

COPY public.faq (faqid, category, question, answer, sortorder) FROM stdin;
1	Leave	How do I apply for leave?	Go to My services > Time off, choose the leave type and dates, and submit. Your manager is notified and the request shows as Pending until it is decided.	1
2	Leave	Can I cancel a leave request?	Yes, while it is still Pending. Open My services > Time off and choose Withdraw next to the request. Approved leave must be cancelled by your manager.	2
3	Leave	How many days of earned leave do I get?	18 days a year, credited at 1.5 days a month. See the Leave policy in Documents for the full rules.	3
4	Payroll	When is salary paid?	On the last working day of each month. Your payslip appears in My services > Payslips the same day.	1
5	Payroll	Where can I find my tax statement?	Open Documents and look under Personal for "Tax statement FY 2025-26". You can download it as a text file.	2
6	Payroll	My payslip looks wrong. What should I do?	Raise a ticket on this page with the category Payroll and mention the month and the amount you expected.	3
7	IT	How do I change my password?	Click your avatar in the top-right corner and choose Change password. Changing it signs you out on every other device.	1
8	IT	My account is locked. What now?	Accounts lock for 15 minutes after 5 wrong passwords. Wait and try again, or ask an administrator to unlock it from the User accounts page.	2
9	IT	How do I get software installed?	Raise an IT ticket with the software name and why you need it. Approved software is installed within 2 working days.	3
10	General	How do I update my phone number or address?	Ask HR by raising a ticket with the category HR. HR can update your profile from the Directory.	1
11	General	How do I borrow a book or course?	Open the Library page and click Borrow. Books are due back in 14 days and you can hold up to 3 items at once.	2
12	Facilities	Who do I contact about my desk, chair or access card?	Raise a ticket with the category Facilities. Urgent issues such as a lost access card are handled the same day.	1
\.


